import {ORDER,ATOMIC,NAMES,tint,ARTIFACTS,RECIPES,UPGRADES,normalizeMeta,rollDay,dailyTasks,claimDaily,resetReactionLevel,reactionReward,runReaction,researchQuest,claimResearch,buyUpgrade,claimSecret,activeSymbols,tablePositions} from './progression.js';
export function initExpansion(api){
 const $=id=>document.getElementById(id);let raw;try{raw=JSON.parse(localStorage.getItem('chemlab_world_v1'))}catch{}const meta=normalizeMeta(raw,api.core().level);let pair=[],busy=false;
 function save(){api.persist();try{localStorage.setItem('chemlab_world_v1',JSON.stringify(meta))}catch{api.say('Не вдалося зберегти розвиток лабораторії на пристрої')}}
 function sync(){rollDay(meta);$('crystal-count').textContent=meta.crystals;$('lab-rank').textContent=1+Object.values(meta.upgrades).reduce((a,b)=>a+b,0);const q=researchQuest(api.core(),meta);$('research-label').textContent=q?`${q.ready?'Відкрити':'Дослідження'} ${q.symbol}`:'Усі елементи відкрито';$('quest-dot').hidden=!dailyTasks(meta).some(t=>meta.daily[t.id]>=t.target&&!meta.daily.claimed.includes(t.id));$('reactor-button').classList.toggle('iced',meta.frozen);$('game').dataset.lab=String(Math.min(3,1+Math.floor(Object.values(meta.upgrades).reduce((a,b)=>a+b,0)/3)));}
 function show(html){api.modal(html);}
 function rewardText(r){return `+${r.gold} монет${r.crystals?' · +'+r.crystals+' ◈':''}${r.artifact?' · '+ARTIFACTS.find(a=>a.id===r.artifact).name:''}`;}
 function effect(type){const el=document.createElement('div');el.className=`reaction-fx fx-${type}`;el.innerHTML=Array.from({length:18},(_,i)=>`<i style="--a:${i*20}deg;--d:${70+i%5*17}px">${type==='freeze'?'❄':type==='gold'?'✦':type==='artifact'?'❖':'◆'}</i>`).join('');document.body.append(el);setTimeout(()=>el.remove(),1100);api.tone(type==='freeze'?300:940);navigator.vibrate?.([20,30,40]);}
 function recipeInfo(r){const unlocked=[r.a,r.b].every(s=>api.core().discovered.includes(s));const rew=reactionReward(r,meta);return `<button class="recipe-card" data-recipe="${r.id}" ${!unlocked?'disabled':''}><span class="formula"><b style="color:${tint(r.a)}">${api.core().discovered.includes(r.a)?r.a:'?'}</b> + <b style="color:${tint(r.b)}">${api.core().discovered.includes(r.b)?r.b:'?'}</b></span><span><strong>${r.name}</strong><small>${rewardText(rew)}${r.type==='freeze'?'<br>❄ Реактор замерзне до наступного ходу':''}</small></span><span>→</span></button>`;}
 function bindRecipes(){document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{const r=RECIPES.find(r=>r.id===b.dataset.recipe);pair=[r.a,r.b];reactor();});}
 function atlas(){const core=api.core(),q=researchQuest(core,meta);show(`<div class="eyebrow">118 КЛІТИНОК · ОДНА ВЕЛИКА ПОДОРОЖ</div><h2>Карта відкриттів</h2><div class="map-summary"><b>${core.discovered.length}<small> / 118 відкрито</small></b><span>◈ ${meta.crystals}</span></div><div class="map-scroll" tabindex="0" aria-label="Періодична таблиця, прокручуйте горизонтально"><div class="periodic">${tablePositions().map(({s,row,col})=>{const open=core.discovered.includes(s);return `<button class="ptable ${open?'known':''} ${q?.symbol===s?'next-element':''}" style="grid-row:${row};grid-column:${col};--el:${tint(s)}" data-element="${s}" aria-label="${open?s:'Невідомий елемент, номер '+(ATOMIC.indexOf(s)+1)}"><small>${ATOMIC.indexOf(s)+1}</small><b>${open?s:'?'}</b></button>`}).join('')}</div></div><p>Проведи вбік, щоб оглянути карту · Натисни на клітинку</p>${q?`<button class="primary" id="map-research">${q.ready?'✦ Відкрити '+q.symbol:'Наступне відкриття: '+q.symbol}</button>`:''}<div class="map-legend"><i></i> відкрито <i class="locked-dot"></i> невідомо <i class="next-dot"></i> наступна ціль</div><p class="fine">Реакції ChemLab — фантастичні ігрові комбінації</p>`);$('modal').classList.add('wide');document.querySelectorAll('[data-element]').forEach(b=>b.onclick=()=>element(b.dataset.element));if(q)$('map-research').onclick=research;}
 function element(s){const open=api.core().discovered.includes(s),q=researchQuest(api.core(),meta),i=ORDER.indexOf(s);show(`<div class="element-hero" style="--el:${tint(s)}"><small>${ATOMIC.indexOf(s)+1}</small>${open?s:'?'}</div><h2>${open?(NAMES[s]||s):'Невідомий елемент'}</h2>${open?`<p>Знайди його партнерів та запускай фантастичні реакції</p>${RECIPES.filter(r=>r.a===s||r.b===s).map(recipeInfo).join('')}`:`<p>${q?.symbol===s?'Твоя наступна ціль дослідження':'Спочатку відкрий попередні елементи дослідницького шляху'}<br>Етап ${i+1} з 118</p><button class="primary" id="to-research">Дослідницьке завдання</button>`}<button class="secondary" id="back-map">← Карта елементів</button>`);$('back-map').onclick=atlas;if($('to-research'))$('to-research').onclick=research;bindRecipes();}
 function research(){const core=api.core(),q=researchQuest(core,meta);if(!q){show('<h2>Карта завершена!</h2><p>Усі 118 елементів відкрито</p>');return}show(`<div class="eyebrow">ДОСЛІДНИЦЬКИЙ КВЕСТ</div><div class="element-hero" style="--el:${tint(q.symbol)}">?</div><h2>Відкрити ${q.symbol}</h2><p>Заверши дві умови, щоб додати елемент на карту та відкрити його реакцію</p><div class="quest-row">Досягни рівня ${q.requiredLevel}<b>${Math.min(core.level,q.requiredLevel)} / ${q.requiredLevel}</b></div><progress value="${Math.min(core.level,q.requiredLevel)}" max="${q.requiredLevel}"></progress><div class="quest-row">Проведи реакції<b>${Math.min(meta.reactions,q.requiredReactions)} / ${q.requiredReactions}</b></div><progress value="${Math.min(meta.reactions,q.requiredReactions)}" max="${q.requiredReactions}"></progress><p>Нагорода: новий елемент + 3 ◈<br>Нові елементи з’являються у наступних головоломках</p><button class="primary" id="unlock" ${q.ready?'':'disabled'}>Відкрити елемент</button><button class="secondary" id="research-reactor">До реактора →</button>`);$('research-reactor').onclick=()=>{pair=[];reactor()};$('unlock').onclick=()=>{const s=claimResearch(core,meta);if(!s)return;save();sync();api.render();effect('crystal');element(s);};}
 function reactor(){resetReactionLevel(meta,api.core().level);const state=api.attempt(),r=pair.length===2?RECIPES.find(r=>[r.a,r.b].every(s=>pair.includes(s))):null;const used=r&&meta.reactionClaims.includes(r.id),quota=3+meta.upgrades.reactor;show(`<div class="eyebrow">ЕКСПЕРИМЕНТАЛЬНИЙ РЕАКТОР</div><h2>${meta.frozen?'Полярна заморозка':'Що буде, якщо…'}</h2><div class="reactor-vessel ${meta.frozen?'frozen':''}"><div class="reactor-orb" style="--el:${pair[0]?tint(pair[0]):'#44646c'}">${pair[0]||'?'}</div><span>+</span><div class="reactor-orb" style="--el:${pair[1]?tint(pair[1]):'#44646c'}">${pair[1]||'?'}</div></div><p>${meta.frozen?'❄ Колба реактора заморожена на один хід. Зроби будь-яке успішне переливання у головоломці.':'Обери два відкриті елементи. Зразки не витрачають фішки з ігрового поля.'}</p><div class="sample-tray">${api.core().discovered.map(s=>`<button class="sample ${pair.includes(s)?'picked':''}" style="--el:${tint(s)}" data-sample="${s}" aria-pressed="${pair.includes(s)}">${s}</button>`).join('')}</div><div class="reaction-preview">${r?`<strong>${r.name}</strong><small>${rewardText(reactionReward(r,meta))}${r.type==='freeze'?'<br>❄ Заморозка реактора до наступного ходу':''}</small>`:pair.length===2?'Стабільна суміш · рецепт не знайдено':'Кожна пара приховує свою історію'}</div><button class="primary" id="mix" ${!r||used||meta.frozen||state.ended||state.locked||busy||meta.reactionClaims.length>=quota?'disabled':''}>${state.ended?'Спочатку почни наступний рівень':used?'Реакція вже зібрана на цьому рівні':meta.frozen?'Зроби хід, щоб розморозити':meta.reactionClaims.length>=quota?'Заряди вичерпано до наступного рівня':'Запустити реакцію'}</button><p>${Math.max(0,quota-meta.reactionClaims.length)} / ${quota} зарядів · нові заряди після перемоги<br>Кожна п’ята реакція дає новий артефакт, поки колекцію не зібрано</p><button class="secondary" id="recipe-book">Книга доступних рецептів</button>`);document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>{const s=b.dataset.sample;if(pair.includes(s))pair=pair.filter(x=>x!==s);else pair=[...pair.slice(-1),s];reactor();});$('recipe-book').onclick=()=>{show(`<h2>Книга реакцій</h2><p>Ігрові рецепти та гарантовані нагороди</p>${RECIPES.filter(r=>[r.a,r.b].every(s=>api.core().discovered.includes(s))).map(recipeInfo).join('')}`);bindRecipes();};$('mix').onclick=()=>{if(busy||api.attempt().ended||api.attempt().locked)return;busy=true;const result=runReaction(api.core(),meta,r.id);busy=false;if(!result)return;save();sync();api.render();effect(result.recipe.type);show(`<div class="eyebrow">РЕАКЦІЯ ВІДКРИТА</div><div class="reward">${{blast:'✺',freeze:'❄',gold:'✦',crystal:'◈',artifact:'❖'}[result.recipe.type]}</div><h2>${result.recipe.name}</h2><p>${rewardText(result.reward)}</p>${result.recipe.type==='freeze'?'<p>Колба реактора замерзла на один хід. Повернися до головоломки та зроби переливання.</p>':''}<button class="primary" id="back-play">Продовжити експеримент →</button><button class="secondary" id="more-reactions">Інша реакція</button>`);$('back-play').onclick=()=>$('modal').close();$('more-reactions').onclick=()=>{pair=[];reactor()};};}
 function quests(){rollDay(meta);save();show(`<div class="eyebrow">ЩОДЕННИК ДОСЛІДНИКА</div><h2>Сьогодні у лабораторії</h2><p>Завдання на ${meta.daily.day} · оновлення о 00:00 UTC</p>${dailyTasks(meta).map(t=>`<section class="quest-card"><div class="quest-row"><strong>${t.title}</strong><b>${Math.min(meta.daily[t.id],t.target)} / ${t.target}</b></div><progress value="${Math.min(meta.daily[t.id],t.target)}" max="${t.target}"></progress><small>+${t.gold} монет · +${t.crystals} ◈</small><button class="secondary" data-claim="${t.id}" ${meta.daily.claimed.includes(t.id)||meta.daily[t.id]<t.target?'disabled':''}>${meta.daily.claimed.includes(t.id)?'✓ Нагороду отримано':'Забрати нагороду'}</button></section>`).join('')}<button class="primary" id="daily-research">Дослідницька місія →</button>`);document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{if(claimDaily(api.core(),meta,b.dataset.claim)){save();sync();api.render();quests();}});$('daily-research').onclick=research;}
 function lab(){show(`<div class="eyebrow">ТВОЯ ЛАБОРАТОРІЯ · РАНГ ${1+Object.values(meta.upgrades).reduce((a,b)=>a+b,0)}</div><h2>Місце великих відкриттів</h2><div class="lab-balance">✦ ${api.core().gold} <span>◈ ${meta.crystals}</span></div>${UPGRADES.map(u=>`<section class="upgrade-card"><span class="upgrade-icon">${u.icon}</span><div><strong>${u.name}</strong><small>Ступінь ${meta.upgrades[u.id]} / 5<br>${u.description}</small></div><button data-upgrade="${u.id}" ${meta.upgrades[u.id]>=5||api.core().gold<u.base*(meta.upgrades[u.id]+1)?'disabled':''}>${meta.upgrades[u.id]>=5?'MAX':u.base*(meta.upgrades[u.id]+1)+' ✦'}</button></section>`).join('')}<button class="primary" id="relics">Артефакти та пасхалки →</button><button class="secondary" id="styles">Оформлення за кристали</button>`);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(buyUpgrade(api.core(),meta,b.dataset.upgrade)){save();sync();api.render();lab();}});$('relics').onclick=relics;$('styles').onclick=styles;}
 function styles(){let skin;try{skin=localStorage.getItem('chemlab_world_skin')}catch{}show(`<h2>Світло твоєї лабораторії</h2><p>Косметичні теми за зароблені кристали · ${meta.crystals} ◈</p>${[['aurora','Полярне сяйво',12],['solar','Сонячна обсерваторія',20]].map(([id,name,cost])=>`<button class="style-card ${id}" data-style="${id}">${name}<small>${skin===id?'✓ Активна тема':cost+' ◈ · обладнати'}</small></button>`).join('')}<button class="secondary" id="clear-style">Класична лабораторія</button>`);document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{const id=b.dataset.style,cost=id==='aurora'?12:20;let owned=[];try{owned=JSON.parse(localStorage.getItem('chemlab_owned_themes')||'[]');if(!Array.isArray(owned))owned=[]}catch{}if(!owned.includes(id)){if(meta.crystals<cost){api.say('Потрібно більше кристалів');b.querySelector('small').textContent='Недостатньо кристалів';return}meta.crystals-=cost;owned.push(id)}try{localStorage.setItem('chemlab_owned_themes',JSON.stringify(owned));localStorage.setItem('chemlab_world_skin',id)}catch{}document.body.dataset.theme=id;save();sync();styles();});$('clear-style').onclick=()=>{document.body.dataset.theme='';try{localStorage.removeItem('chemlab_world_skin')}catch{};styles()};}
 function relics(){const secrets=[['first','Перша іскра',meta.reactions>=1],['collector','Хранитель реліквій',meta.artifacts.length>=3],['explorer','За горизонтом',api.core().discovered.length>=10]];show(`<div class="eyebrow">СКАРБИ ЛАБОРАТОРІЇ</div><h2>Колекція артефактів</h2><div class="relic-grid">${ARTIFACTS.map(a=>`<div class="relic ${meta.artifacts.includes(a.id)?'owned':''}"><span>${meta.artifacts.includes(a.id)?a.icon:'?'}</span><small>${meta.artifacts.includes(a.id)?a.name:'Невідомий артефакт'}</small></div>`).join('')}</div><p>Реакцій проведено: ${meta.reactions} · До наступної реліквії: ${5-meta.reactions%5}</p><h3>Приховані досягнення</h3>${secrets.map(([id,name,ready])=>`<button class="secondary" data-secret="${id}" ${!ready||meta.secrets.includes(id)?'disabled':''}>${ready?name:'???'} · ${meta.secrets.includes(id)?'✓':ready?'+100 ✦ +5 ◈':'Секрет'}</button>`).join('')}`);document.querySelectorAll('[data-secret]').forEach(b=>b.onclick=()=>{if(claimSecret(api.core(),meta,b.dataset.secret)){save();sync();api.render();effect('artifact');relics();}});}
 $('atlas').onclick=atlas;$('research-button').onclick=research;$('quests-button').onclick=quests;$('lab-button').onclick=lab;$('reactor-button').onclick=()=>{pair=[];reactor()};
 try{const skin=localStorage.getItem('chemlab_world_skin');if(['aurora','solar'].includes(skin))document.body.dataset.theme=skin}catch{}
 rollDay(meta);sync();save();
 return {atlas,symbols:()=>activeSymbols(api.core()),onStart(){resetReactionLevel(meta,api.core().level);save();sync()},onMove(){if(meta.frozen){meta.frozen=false;api.say('❄ Лід розтанув · реактор знову готовий')}save();sync()},onWin(clean){rollDay(meta);meta.wins++;meta.daily.wins++;if(clean)meta.daily.clean++;save();sync()},sync,research};
}
